parameters.jsCode:
// Expense policy engine: hard rejections, soft flags for manager review, duplicate detection.
// Duplicate keys use workflow static data, which n8n persists for active (production) executions only.
const cfg = $('Config · Expense Policy').first().json;
const ctx = $('Intake · Attach Receipt Image').first().json;
const employee = ctx.employee;
const store = $getWorkflowStaticData('global');
store.expenseKeys = store.expenseKeys || [];

const toNum = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Math.round(Number(v) * 100) / 100);
const text = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
const keyPart = (v) => String(v || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const limits = typeof cfg.categoryLimits === 'string' ? JSON.parse(cfg.categoryLimits) : cfg.categoryLimits;

let data = $input.first().json.output;
if (typeof data === 'string') {
  try { data = JSON.parse(data.replace(/```json\s*|```/g, '').trim()); } catch (e) { data = null; }
}
data = data && typeof data === 'object' ? data : {};

const merchant = data.merchant || {};
const receipt = data.receipt || {};
const t = data.totals || {};
const cls = data.classification || {};
const meta = data.extraction || {};
const items = (Array.isArray(data.items) ? data.items : []).map((i) => ({
  description: text(i.description), quantity: toNum(i.quantity), unit_price: toNum(i.unit_price), total: toNum(i.total),
}));
const total = toNum(t.total);
const category = cls.category || 'Other';
const rejections = [];
const flags = [];

// Hard rejections: the employee must resubmit
if (!Object.keys(data).length) rejections.push('The receipt could not be read. Please send a clearer photo.');
if (meta.is_receipt === false) rejections.push('This image is not a receipt or proof of purchase.');
if (meta.legible === false) rejections.push('The receipt is not legible. Please retake the photo in good light.');
if (!(total > 0)) rejections.push('No total amount found on the receipt.');
const dateOk = /^\d{4}-\d{2}-\d{2}$/.test(receipt.date || '') && !isNaN(Date.parse(receipt.date));
const ageDays = dateOk ? Math.floor((Date.now() - Date.parse(receipt.date)) / 86400000) : null;
if (!dateOk) rejections.push('No valid purchase date found on the receipt.');
else if (ageDays > cfg.maxReceiptAgeDays) rejections.push(`Receipt is ${ageDays} days old; policy allows ${cfg.maxReceiptAgeDays} days.`);
else if (ageDays < -1) rejections.push('Receipt date is in the future.');

const expenseKey = `${employee.id}-${keyPart(merchant.name)}-${receipt.date || 'NODATE'}-${total ?? 0}`;
if (store.expenseKeys.includes(expenseKey)) rejections.push('This receipt was already submitted.');

// Soft flags: require manager approval
const limit = limits[category] ?? limits.Other;
if (total > limit) flags.push(`${category} limit is ${cfg.baseCurrency} ${limit}; this receipt is ${total}.`);
if (total >= cfg.autoApproveLimit) flags.push(`Amount at or above auto-approve limit (${cfg.autoApproveLimit}).`);
if (cls.contains_alcohol) flags.push('Receipt contains alcohol (not reimbursable without approval).');
if (dateOk && [0, 6].includes(new Date(receipt.date).getUTCDay())) flags.push('Purchase made on a weekend.');
if (typeof meta.confidence === 'number' && meta.confidence < cfg.confidenceThreshold) flags.push(`Low AI confidence (${meta.confidence}).`);
const itemSum = toNum(items.reduce((s, i) => s + (i.total || 0), 0));
if (items.length && total > 0 && Math.abs(itemSum + (toNum(t.tip) || 0) - total) > Math.max(0.05, total * 0.02) && Math.abs(itemSum + (toNum(t.tax) || 0) + (toNum(t.tip) || 0) - total) > Math.max(0.05, total * 0.02)) {
  flags.push(`Line items (${itemSum}) do not reconcile to total (${total}).`);
}

const decision = rejections.length ? 'REJECTED' : flags.length ? 'MANAGER_APPROVAL' : 'AUTO_APPROVED';
if (decision !== 'REJECTED') store.expenseKeys = [...store.expenseKeys, expenseKey].slice(-20000);

return [{
  json: {
    expense_key: expenseKey,
    decision,
    rejections,
    policy_flags: flags,
    warnings: Array.isArray(meta.warnings) ? meta.warnings : [],
    employee_id: employee.id,
    employee_name: employee.full_name,
    department: employee.department,
    cost_center: employee.cost_center,
    approver_chat_id: employee.manager_telegram_chat_id || cfg.financeApproverChatId,
    merchant_name: text(merchant.name),
    merchant_tax_id: text(merchant.tax_id),
    merchant_country: text(merchant.country),
    receipt_number: text(receipt.receipt_number),
    receipt_date: dateOk ? receipt.date : null,
    currency: text(receipt.currency) || cfg.baseCurrency,
    payment_method: receipt.payment_method || null,
    category,
    contains_alcohol: !!cls.contains_alcohol,
    subtotal: toNum(t.subtotal),
    tax: toNum(t.tax),
    tip: toNum(t.tip),
    total,
    items,
    confidence: meta.confidence ?? null,
    employee_note: ctx.caption,
    telegram_chat_id: $('Intake · Telegram Receipt Bot').first().json.message.chat.id,
    telegram_file_id: ($('Intake · Telegram Receipt Bot').first().json.message.photo || []).slice(-1)[0]?.file_id ?? null,
    execution_id: $execution.id,
  },
}];

