// Merge the manager's Telegram decision back onto the expense.
const expense = $('Policy · Evaluate Expense').first().json;
const approved = $json.data?.approved;
return [{
  json: {
    ...expense,
    status: approved === true ? 'APPROVED' : approved === false ? 'REJECTED' : 'APPROVAL_TIMEOUT',
    approved_by_chat_id: expense.approver_chat_id,
    decided_at: $now.toISO(),
  },
}];

// Final expense record + the confirmation message sent back to the employee.
const e = { ...$input.first().json };
if (!e.status) e.status = e.decision === 'AUTO_APPROVED' ? 'APPROVED' : 'REJECTED';
const money = (v) => `${e.currency} ${Number(v || 0).toFixed(2)}`;

const headline = {
  APPROVED: '✅ *Expense approved*',
  REJECTED: '❌ *Expense not accepted*',
  APPROVAL_TIMEOUT: '⏳ *Approval timed out*. Finance will follow up.',
}[e.status];
const reasons = e.status === 'REJECTED' ? (e.rejections.length ? e.rejections : ['Declined by your manager.']) : e.policy_flags;

e.reply_text = [
  headline,
  `${e.merchant_name || 'Unknown merchant'} · ${e.receipt_date || 'no date'}`,
  `Amount: *${money(e.total)}* · ${e.category}`,
  reasons.length ? `\n${e.status === 'REJECTED' ? 'Reason' : 'Notes'}:\n• ${reasons.join('\n• ')}` : null,
  e.status === 'APPROVED' ? '\nIt will be included in your next reimbursement run.' : null,
].filter(Boolean).join('\n');

return [{ json: e }];

// Monthly finance pack: HTML summary by department and category, with the CSV detail attached.
const rows = $('Report · Fetch Last Month Expenses').all().map((r) => r.json).filter((r) => r.status);
const sum = (list) => list.reduce((s, r) => s + Number(r.total_base || 0), 0);
const approved = rows.filter((r) => r.status === 'APPROVED');
const group = (key) => Object.entries(approved.reduce((acc, r) => ((acc[r[key]] = (acc[r[key]] || 0) + Number(r.total_base || 0)), acc), {}))
  .sort((a, b) => b[1] - a[1]);
const table = (title, entries) => `<h3>${title}</h3><table cellpadding="6" style="border-collapse:collapse">${entries
  .map(([k, v]) => `<tr><td style="border-bottom:1px solid #ddd">${k}</td><td style="border-bottom:1px solid #ddd;text-align:right">${v.toFixed(2)}</td></tr>`).join('')}</table>`;
const period = $now.minus({ months: 1 }).toFormat('LLLL yyyy');

return [{
  json: {
    subject: `Expense report · ${period} · ${approved.length} approved · ${sum(approved).toFixed(2)}`,
    html: `<h2>Expense report: ${period}</h2>
<p><b>${rows.length}</b> receipts submitted · <b>${approved.length}</b> approved (${sum(approved).toFixed(2)}) ·
<b>${rows.filter((r) => r.status === 'REJECTED').length}</b> rejected · <b>${rows.filter((r) => r.status === 'APPROVAL_TIMEOUT').length}</b> awaiting follow-up.</p>
${table('Approved spend by department', group('department'))}
${table('Approved spend by category', group('category'))}
<p>Full line-level detail is attached as CSV.</p><p style="color:#888">AI Expense Receipt Assistant</p>`,
  },
  binary: $input.first().binary,
}];
